INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('S15-fleet-matrix', 'I', 'Factorial scoring of the replayed NQ fleet (8,207 variants, 2021–2026): every single overlay paired against its own base OOS (train <2025-03 / test ≥), overlay × timeframe, family × timeframe survival, and VIX / prior-day-type / gap / weekday regimes as post-hoc filters on every strategy vs a random-day control; then the composite of the robust pieces', 'NQ', '2021–2026', NULL, 0.98, NULL, NULL, 'no edge', 'OVERLAYS (share of bases improved in test): level overlays lv_room/lv_tgt/lv_conf/lv_stop 77–85% (robust on 1/5/15m, but median test PF only 0.50–0.55 vs base 0.40 — they lose less), rvol15 64%, tr25 62%; regime presets 34–55% (chance); ALL BOOK OVERLAYS HURT (imb/micro/all/sg 18–30%, bx/btp/bbe 0–5%). FAMILY × TF: best cells pdhl_breakout 5m 23%, hold 1m 19% (the weakness holds), roc/supertrend/keltner 15m 12–15% PF>1 in both halves; all else ≤7%; 1m/ORB/mtf ≈0–1%. REGIMES: strategy × VIX≥20 cells survive both halves 1.3% vs 0.5% random (2.6×), prior-day trend_down 2.2%; gap size, weekday, VIX<20 = chance. COMPOSITE (15m/5m momentum + ORB time-stop families, 729 ids): pooled PF test 0.63 → 0.81 with level overlay → 0.98 with level overlay AND VIX≥20 — breakeven after costs, not profit; 2 of 58 cells PF>1.3 both halves (3%, control 6%); a train-chosen basket makes +$16/day on VIX≥20 test days and 0% weekly payout cadence at 2–5 MNQ. The 12,031-id cross-filter combo grid has NO history yet (queue, lowest priority).', '2026-10-11')
